inline double lambda(double x) {
  if (x < 0.0) return 1.0 / bvn_tail::mills(-x);
  return bvn_tail::pdf(x) / (1.0 - bvn_tail::Qd(x));
}

inline double log_Phi(double x) { return bvn_tail::log_Phi(x); }

inline double h_at(int n, const double* a, const double* c, double z) {
  double h = -0.5 * z * z;
  for (int j = 0; j < n; ++j) h += log_Phi(a[j] * z + c[j]);
  return h;
}

inline double log_int(int n, const double* a, const double* c, double* dc, double* da) {
  double z = 0.0, hz = h_at(n, a, c, z), h2 = -1.0;
  for (int it = 0; it < 60; ++it) {
    double g = -z;
    h2 = -1.0;
    for (int j = 0; j < n; ++j) {
      double x = a[j] * z + c[j], l = lambda(x);
      g += a[j] * l;
      h2 -= a[j] * a[j] * l * (x + l);
    }
    double step = -g / h2;
    if (std::fabs(step) < 1e-13 * (1.0 + std::fabs(z))) break;
    double zn = z + step, hn = h_at(n, a, c, zn);
    while (hn < hz && std::fabs(step) > 1e-15) {
      step *= 0.5;
      zn = z + step;
      hn = h_at(n, a, c, zn);
    }
    z = zn;
    hz = hn;
  }
  h2 = -1.0;
  for (int j = 0; j < n; ++j) {
    double x = a[j] * z + c[j], l = lambda(x);
    h2 -= a[j] * a[j] * l * (x + l);
  }
  const double s = 1.0 / std::sqrt(-h2);
  const int K = n <= 3 ? 32 : n <= 7 ? 48 : n <= 20 ? 64 : 96;
  const double* X = n <= 3 ? kX32 : n <= 7 ? kX48 : n <= 20 ? kX64 : kX96;
  const double* LW = n <= 3 ? kLW32 : n <= 7 ? kLW48 : n <= 20 ? kLW64 : kLW96;
  double g[96], zi[96], gmax = -bvn_tail::kInf;
  for (int i = 0; i < K; ++i) {
    zi[i] = z + s * X[i];
    g[i] = h_at(n, a, c, zi[i]) - hz + LW[i];
    if (g[i] > gmax) gmax = g[i];
  }
  double sum = 0.0;
  for (int i = 0; i < K; ++i) {
    g[i] = std::exp(g[i] - gmax);
    sum += g[i];
  }
  for (int j = 0; j < n; ++j) {
    dc[j] = 0.0;
    da[j] = 0.0;
  }
  for (int i = 0; i < K; ++i) {
    double w = g[i] / sum;
    for (int j = 0; j < n; ++j) {
      double l = w * lambda(a[j] * zi[i] + c[j]);
      dc[j] += l;
      da[j] += l * zi[i];
    }
  }
  return hz + std::log(s) + gmax + std::log(sum) - bvn_tail::kLogSqrt2Pi;
}

